'use strict';
/* Exhaustion Q490 SELL Stage 2: expand trade count while preserving quality. Research only. */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';
const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function atr(c,p=14){const a=Array(c.length).fill(NaN),q=[];let s=0;for(let i=1;i<c.length;i++){const tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));q.push(tr);s+=tr;if(q.length>p)s-=q.shift();if(q.length===p)a[i]=s/p}return a}
function adx(c,p=14){const o=Array(c.length).fill(NaN),tr=Array(c.length).fill(0),pd=Array(c.length).fill(0),md=Array(c.length).fill(0);for(let i=1;i<c.length;i++){const up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pd[i]=up>dn&&up>0?up:0;md[i]=dn>up&&dn>0?dn:0;tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c))}let tn=0,pn=0,mn=0;for(let i=1;i<=p;i++){tn+=tr[i];pn+=pd[i];mn+=md[i]}const dx=Array(c.length).fill(NaN);for(let i=p;i<c.length;i++){if(i>p){tn=tn-tn/p+tr[i];pn=pn-pn/p+pd[i];mn=mn-mn/p+md[i]}if(tn>0){const a=100*pn/tn,b=100*mn/tn;if(a+b>0)dx[i]=100*Math.abs(a-b)/(a+b)}}let seed=0,n=0,last=NaN;for(let i=p;i<c.length;i++){if(!Number.isFinite(dx[i]))continue;if(n<p){seed+=dx[i];n++;if(n===p)last=o[i]=seed/p}else last=o[i]=(last*(p-1)+dx[i])/p}return o}
const A=atr(M),X=adx(M);
function run(q){let out=[],p=null;for(let i=250;i<M.length-1;i++){if(p){const b=M[i],sl=b.h>=p.sl,tp=b.l<=p.tp;if(sl||tp||i-p.ei+1>=3){const px=sl?p.sl:tp?p.tp:b.c;out.push({t:p.t,r:(p.en-px)/p.risk,h:p.h});p=null}}if(p)continue;const ex=i-1;if(!Number.isFinite(A[ex])||!Number.isFinite(X[ex]))continue;const hr=new Date(M[ex].t).getUTCHours();if(q.blocks.includes(hr)||X[ex]>q.ax)continue;const b=M[ex],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg>q.bm)continue;const disp=M[ex-1].c-M[ex-q.lookback].c;if(!(disp>0)||disp<A[ex]*q.burst)continue;let agree=0;for(let k=ex-q.lookback;k<ex;k++)if(M[k].c>M[k].o)agree++;if(agree<q.agree)continue;const uw=(b.h-Math.max(b.o,b.c))/rg;if(uw<q.w)continue;const cf=M[i];if(cf.c>=b.h-rg*q.r||cf.h>b.h+A[ex]*q.over)continue;const en=M[i+1].o,risk=Math.max(A[ex]*1.75,2),reward=Math.max(A[ex]*1.5,2);p={en,risk,sl:en+risk,tp:en-reward,ei:i+1,t:M[i].t,h:hr}}return out}
function S(a){let w=0,gp=0,gl=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}
const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const BASE={burst:2.6,w:.30,r:.15,ax:32,bm:.50,blocks:[1,5,23],lookback:3,agree:2,over:.25},b=S(run(BASE));
console.log('EXHAUSTION SELL — STAGE 2 EXPANSION');console.log('Q490 BASE',F(b));if(!(b.n===52&&Math.abs(b.wr-57.7)<.2)){console.log('❌ BASE PARITY FAIL');process.exit(3)}
const end=M.at(-1).t;
const blockSets=[[1,5,23],[1,5,15,23],[1,5,20,23],[1,5,22,23],[1,5,15,20,23],[1,5,20,22,23]];
let c=[];for(const burst of [2.2,2.4,2.6])for(const w of [.20,.25,.30])for(const r of [.10,.15,.20])for(const ax of [28,30,32])for(const bm of [.50,.55,.60])for(const over of [.25,.30,.35])for(const blocks of blockSets){const q={burst,w,r,ax,bm,blocks,lookback:3,agree:2,over},a=run(q),s=S(a);if(s.n<50||s.n>85||s.wr<59||s.pf<1.45||s.dd>5)continue;const r180=S(a.filter(x=>x.t>=end-180*864e5)),r90=S(a.filter(x=>x.t>=end-90*864e5));let folds=0,pos=0;for(let k=0;k<4;k++){const lo=M[Math.floor(M.length*k/4)].t,hi=k===3?Infinity:M[Math.floor(M.length*(k+1)/4)].t,z=S(a.filter(x=>x.t>=lo&&x.t<hi));if(z.n>=8&&z.pf>=1.05)folds++;if(z.net>0)pos++}const score=s.wr*2+s.pf*10+s.net*.35+r180.pf*2+r90.pf+folds*2+pos-s.dd-(Math.abs(s.n-65)*.08);c.push({q,s,r180,r90,folds,pos,score})}
c.sort((a,b)=>b.score-a.score);
console.log(`TESTED ${3*3*3*3*3*3*blockSets.length} | RETAINED ${c.length}`);
console.log('\n🏆 TOP 25 — COUNT × QUALITY');c.slice(0,25).forEach((x,i)=>console.log(`${String(i+1).padStart(2)} | burst${x.q.burst} wick${x.q.w} ret${x.q.r} ADX${x.q.ax} body${x.q.bm} over${x.q.over} block[${x.q.blocks.join(',')}] | ${F(x.s)} | 180D ${F(x.r180)} | 90D ${F(x.r90)} | folds ${x.folds}/4 pos ${x.pos}/4`));
console.log('\n🎯 STRICT TARGETS T55-75 WR>=61 PF>=1.65');
const strict=c.filter(x=>x.s.n>=55&&x.s.n<=75&&x.s.wr>=61&&x.s.pf>=1.65&&x.folds>=3&&x.pos>=3);
if(!strict.length)console.log('No strict candidate — do NOT force it.');else strict.slice(0,15).forEach((x,i)=>console.log(`${i+1} | ${F(x.s)} | burst${x.q.burst} wick${x.q.w} ret${x.q.r} ADX${x.q.ax} body${x.q.bm} over${x.q.over} block[${x.q.blocks.join(',')}] | 180D ${F(x.r180)} | 90D ${F(x.r90)} | folds ${x.folds}/4`));
